<h1 class="h3">Tableau de bord administrateur</h1><section id="utilisateurs" class="my-4"><h2 class="h4">Utilisateurs</h2><div class="table-responsive"><table class="table table-striped"><thead class="table-dark"><tr><th>Nom</th><th>Prénom</th><th>Email</th><th>Téléphone</th><th>Rôle</th></tr></thead><tbody><?php foreach ($users as $entry): ?><tr><td><?= e($entry['last_name']) ?></td><td><?= e($entry['first_name']) ?></td><td><?= e($entry['email']) ?></td><td><?= e($entry['phone']) ?></td><td><?= e($entry['role']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section id="agences" class="my-5"><h2 class="h4">Agences</h2><form method="post" action="/admin/agencies" class="row g-2 mb-3"><?= token() ?><div class="col-auto"><label class="visually-hidden" for="new-agency">Nouvelle agence</label><input class="form-control" id="new-agency" name="name" maxlength="100" required placeholder="Nom de l’agence"></div><div class="col-auto"><button class="btn btn-dark">Ajouter</button></div></form><div class="table-responsive"><table class="table table-striped"><thead class="table-dark"><tr><th>Ville</th><th>Actions</th></tr></thead><tbody><?php foreach ($agencies as $agency): ?><tr><td><?= e($agency['name']) ?></td><td><form method="post" action="/admin/agencies/<?= (int) $agency['id'] ?>" class="d-inline-flex gap-2 align-items-center"><?= token() ?><label class="visually-hidden" for="agency<?= (int) $agency['id'] ?>">Renommer <?= e($agency['name']) ?></label><input id="agency<?= (int) $agency['id'] ?>" class="form-control" name="name" maxlength="100" value="<?= e($agency['name']) ?>" required><button class="btn btn-sm btn-outline-dark">Enregistrer</button></form> <form method="post" action="/admin/agencies/<?= (int) $agency['id'] ?>/delete" class="d-inline" onsubmit="return confirm('Supprimer cette agence ?')"><?= token() ?><button class="btn btn-sm btn-outline-danger">Supprimer</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
<section id="trajets" class="my-5"><h2 class="h4">Tous les trajets</h2><a class="btn btn-dark mb-3" href="/trips/new">Créer un trajet</a><div class="table-responsive"><table class="table table-striped"><thead class="table-dark"><tr><th>Départ</th><th>Arrivée</th><th>Date départ</th><th>Date arrivée</th><th>Places</th><th>Contact</th><th>Actions</th></tr></thead><tbody><?php foreach ($trips as $trip): ?><tr><td><?= e($trip['departure_name']) ?></td><td><?= e($trip['arrival_name']) ?></td><td><?= e($trip['departure_at']) ?></td><td><?= e($trip['arrival_at']) ?></td><td><?= e($trip['available_seats']) ?>/<?= e($trip['total_seats']) ?></td><td><?= e($trip['first_name'] . ' ' . $trip['last_name']) ?><br><?= e($trip['phone']) ?><br><?= e($trip['email']) ?></td><td><a class="btn btn-sm btn-outline-dark" href="/trips/<?= (int) $trip['id'] ?>/edit">Modifier</a> <form method="post" action="/trips/<?= (int) $trip['id'] ?>/delete" class="d-inline" onsubmit="return confirm('Supprimer ce trajet ?')"><?= token() ?><button class="btn btn-sm btn-outline-danger">Supprimer</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
